import React, { useState } from "react";
import "./Dashboard.css";

function Dashboard({ onLogout }) {
  // Task state
  const [tasks, setTasks] = useState([]);
  const [newTaskName, setNewTaskName] = useState("");
  const [newTaskDesc, setNewTaskDesc] = useState("");
  const [editingTaskId, setEditingTaskId] = useState(null);
  const [editName, setEditName] = useState("");
  const [editDesc, setEditDesc] = useState("");
  const [editStatus, setEditStatus] = useState("Pending");

  // Event state
  const [events, setEvents] = useState([]);
  const [newEventName, setNewEventName] = useState("");
  const [newEventDate, setNewEventDate] = useState("");
  const [editingEventId, setEditingEventId] = useState(null);
  const [editEventName, setEditEventName] = useState("");
  const [editEventDate, setEditEventDate] = useState("");

  // Add Task
  const addTask = () => {
    if (!newTaskName.trim()) return;
    const newTask = {
      id: Date.now(),
      name: newTaskName,
      description: newTaskDesc,
      status: "Pending"
    };
    setTasks([...tasks, newTask]);
    setNewTaskName(""); setNewTaskDesc("");
  };

  // Update Task Status
  const updateStatus = (id, status) => {
    setTasks(tasks.map(task =>
      task.id === id ? { ...task, status } : task
    ));
  };

  // Edit Task
  const startEditTask = (task) => {
    setEditingTaskId(task.id);
    setEditName(task.name);
    setEditDesc(task.description);
    setEditStatus(task.status);
  };

  const saveEditTask = (id) => {
    setTasks(tasks.map(task =>
      task.id === id ? { ...task, name: editName, description: editDesc, status: editStatus } : task
    ));
    setEditingTaskId(null); setEditName(""); setEditDesc(""); setEditStatus("Pending");
  };

  // Delete Task
  const deleteTask = (id) => {
    setTasks(tasks.filter(task => task.id !== id));
  };

  // Add Event
  const addEvent = () => {
    if (!newEventName.trim() || !newEventDate) return;
    const newEvent = { id: Date.now(), name: newEventName, date: newEventDate };
    setEvents([...events, newEvent]);
    setNewEventName(""); setNewEventDate("");
  };

  // Edit Event
  const startEditEvent = (event) => {
    setEditingEventId(event.id);
    setEditEventName(event.name);
    setEditEventDate(event.date);
  };

  const saveEditEvent = (id) => {
    setEvents(events.map(event =>
      event.id === id ? { ...event, name: editEventName, date: editEventDate } : event
    ));
    setEditingEventId(null); setEditEventName(""); setEditEventDate("");
  };

  // Delete Event
  const deleteEvent = (id) => {
    setEvents(events.filter(event => event.id !== id));
  };

  // Productivity Score
  const totalTasks = tasks.length;
  const completedTasks = tasks.filter(task => task.status === "Completed").length;
  const productivityScore = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

  return (
    <div className="dashboard-container">
      {/* Header with Logout */}
      <div className="dashboard-header">
        <h1 className="dashboard-title">Nityo Dashboard</h1>
        <button className="logout-btn" onClick={onLogout}>Logout</button>
      </div>

      {/* Add Task */}
      <div className="dashboard-card">
        <div className="emoji">✏️</div>
        <h3>Add Task</h3>
        <input type="text" placeholder="Task Name" value={newTaskName} onChange={(e) => setNewTaskName(e.target.value)} />
        <input type="text" placeholder="Task Description" value={newTaskDesc} onChange={(e) => setNewTaskDesc(e.target.value)} />
        <button className="action-btn" onClick={addTask}>Add Task</button>
      </div>

      {/* Task List */}
      <div className="dashboard-card">
        <div className="emoji">✅</div>
        <h3>Tasks</h3>
        {tasks.length > 0 ? tasks.map(task => (
          <div key={task.id} className="task-item">
            {editingTaskId === task.id ? (
              <>
                <input type="text" value={editName} onChange={(e) => setEditName(e.target.value)} />
                <input type="text" value={editDesc} onChange={(e) => setEditDesc(e.target.value)} />
                <select value={editStatus} onChange={(e) => setEditStatus(e.target.value)}>
                  <option>Pending</option>
                  <option>In-Progress</option>
                  <option>Completed</option>
                </select>
                <button className="action-btn" onClick={() => saveEditTask(task.id)}>Save</button>
              </>
            ) : (
              <>
                <span><strong>{task.name}</strong> — {task.description} ({task.status})</span>
                <select value={task.status} onChange={(e) => updateStatus(task.id, e.target.value)}>
                  <option>Pending</option>
                  <option>In-Progress</option>
                  <option>Completed</option>
                </select>
                <button className="action-btn" onClick={() => startEditTask(task)}>Edit</button>
                <button className="action-btn delete-btn" onClick={() => deleteTask(task.id)}>Delete</button>
              </>
            )}
          </div>
        )) : <p>No tasks yet</p>}
      </div>

      {/* Reports */}
      <div className="dashboard-card">
        <div className="emoji">📊</div>
        <h3>Reports</h3>
        <p>Total Tasks: {totalTasks}</p>
        <p>Completed: {completedTasks}</p>
        <p>Productivity Score: {productivityScore}%</p>
        <div className="progress-bar">
          <div className="progress-fill" style={{ width: `${productivityScore}%` }}></div>
        </div>
      </div>

      {/* Events */}
      <div className="dashboard-card">
        <div className="emoji">📅</div>
        <h3>Events</h3>
        <input type="text" placeholder="Event Name" value={newEventName} onChange={(e) => setNewEventName(e.target.value)} />
        <input type="date" value={newEventDate} onChange={(e) => setNewEventDate(e.target.value)} />
        <button className="action-btn" onClick={addEvent}>Add Event</button>

        {events.length > 0 ? events.map(event => (
          <div key={event.id} className="event-item">
            {editingEventId === event.id ? (
              <>
                <input type="text" value={editEventName} onChange={(e) => setEditEventName(e.target.value)} />
                <input type="date" value={editEventDate} onChange={(e) => setEditEventDate(e.target.value)} />
                <button className="action-btn" onClick={() => saveEditEvent(event.id)}>Save</button>
              </>
            ) : (
              <>
                <span><strong>{event.name}</strong> — {event.date}</span>
                <button className="action-btn" onClick={() => startEditEvent(event)}>Edit</button>
                <button className="action-btn delete-btn" onClick={() => deleteEvent(event.id)}>Delete</button>
              </>
            )}
          </div>
        )) : <p>No events yet</p>}
      </div>

      {/* Theme Toggle */}
      <div className="dashboard-card">
        <div className="emoji">🌙☀️</div>
        <button className="action-btn" onClick={() => document.body.classList.toggle("dark-mode")}>
          Toggle Theme
        </button>
      </div>
    </div>
  );
}

export default Dashboard;
